-- Guardia de texto plano en las tablas hijas y en inquiries (aditiva).
-- El dueño se resuelve por la fila padre. Si el padre no existe, se usa NEW.user_id;
-- si tampoco hay cuenta, la condición no aborta y decide la clave foránea.
-- Reaplicable: CREATE TRIGGER IF NOT EXISTS.

CREATE TRIGGER IF NOT EXISTS document_items_e2e_guard_insert BEFORE INSERT ON document_items FOR EACH ROW WHEN (SELECT encryption_mode FROM user WHERE id = COALESCE((SELECT user_id FROM documents WHERE id = NEW.document_id), NEW.user_id)) IS NOT NULL AND (SELECT encryption_mode FROM user WHERE id = COALESCE((SELECT user_id FROM documents WHERE id = NEW.document_id), NEW.user_id)) != 'server' BEGIN SELECT RAISE(ABORT, 'e2e_account_plaintext_write'); END;
CREATE TRIGGER IF NOT EXISTS document_items_e2e_guard_update BEFORE UPDATE ON document_items FOR EACH ROW WHEN (SELECT encryption_mode FROM user WHERE id = COALESCE((SELECT user_id FROM documents WHERE id = NEW.document_id), NEW.user_id)) IS NOT NULL AND (SELECT encryption_mode FROM user WHERE id = COALESCE((SELECT user_id FROM documents WHERE id = NEW.document_id), NEW.user_id)) != 'server' BEGIN SELECT RAISE(ABORT, 'e2e_account_plaintext_write'); END;

